'use strict';
const $=id=>document.getElementById(id), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='card_archive_v010', PREF='card_archive_preferences_v010';
const uid=()=>crypto.randomUUID?.()||('id-'+Date.now()+'-'+Math.random().toString(36).slice(2));
const initial=()=>({version:1,binders:[],cards:[],tags:[]});
function load(){try{const x=JSON.parse(localStorage.getItem(KEY));return x&&Array.isArray(x.binders)&&Array.isArray(x.cards)&&Array.isArray(x.tags)?x:initial()}catch{return initial()}}
let db=load(),view={binder:null,card:null,search:false},words=[],filters=[],draft='',sort='default',editMode=false,selected=new Set(),prefs=(()=>{try{return JSON.parse(localStorage.getItem(PREF))||{}}catch{return {}}})();
function save(next){const json=JSON.stringify(next);localStorage.setItem(KEY,json);db=next;render()}
function update(fn){const next=structuredClone(db);fn(next);save(next)}
function notify(msg){$('toast').textContent=msg;$('toast').style.display='block';clearTimeout(notify.t);notify.t=setTimeout(()=>$('toast').style.display='none',2400)}
function modal(title,body,actions=[]){$('modalRoot').innerHTML=`<div class="modalShade"><div class="modal"><h2>${esc(title)}</h2>${body}<div class="actions" id="modalActions"></div></div></div>`;const root=$('modalRoot'),bar=$('modalActions');for(const a of actions){const b=document.createElement('button');b.textContent=a.text||'✓';b.title=a.title||a.text;b.className=a.class||'';b.onclick=()=>a.fn?.();bar.append(b)}root.querySelector('.modalShade').addEventListener('click',e=>{if(e.target.classList.contains('modalShade')){if(root.querySelector('.modal[data-editor]'))safeCloseEditor();else closeModal()}});return root}
function closeModal(){ $('modalRoot').innerHTML='' }
function confirmText(title,message,token,onYes){modal(title,`<p>${message}</p><label class="field">Type <b>${token}</b> to confirm<input id="confirmWord" autocomplete="off"></label>`,[{text:'✕',title:'Cancel',fn:closeModal},{text:'✓',title:'Confirm',fn:()=>{if($('confirmWord').value!==token)return notify('Confirmation does not match');onYes();closeModal()}}])}
function confirmEdit(onYes,subject='this card'){modal(`Edit ${subject}?`,`<p>Do you want to make changes?</p>`,[{text:'✕',title:'Cancel',fn:closeModal},{text:'✓',title:'Edit',fn:()=>{closeModal();onYes()}}])}
const dateInput=value=>/^\d{4}-\d{2}-\d{2}$/.test(value||'')?value.slice(8)+'-'+value.slice(5,7)+'-'+value.slice(0,4):(value||'');
const parseDate=value=>{const m=/^(\d{2})-(\d{2})-(\d{4})$/.exec((value||'').trim());if(!m)return null;const iso=`${m[3]}-${m[2]}-${m[1]}`;const d=new Date(iso+'T12:00:00');return d.getFullYear()===+m[3]&&d.getMonth()+1===+m[2]&&d.getDate()===+m[1]?iso:null};
const displayDate=value=>/^\d{4}-\d{2}-\d{2}$/.test(value||'')?value.slice(8,10)+'-'+value.slice(5,7)+'-'+value.slice(0,4):(value||'—');
const binderName=id=>db.binders.find(b=>b.id===id)?.name||'Unknown binder';
function cardText(c){return [c.name,c.condition,c.language,c.pack,c.dateBought,c.description,...(c.copies||[]).flatMap(x=>[x.condition,x.language,x.pack,x.dateBought,x.description]),binderName(c.binderId),...c.tags.map(t=>db.tags.find(x=>x.id===t)?.name||'')].join(' ').toLowerCase()}
function matches(c){const text=cardText(c);return words.every(w=>text.includes(w.toLowerCase()))&&filters.every(t=>c.tags.includes(t))&&(!draft||text.includes(draft.toLowerCase()))}
function activeSort(){return view.binder&&!view.search?(prefs.binderSort?.[view.binder]||'default'):sort}
function allImageIds(cards){return cards.flatMap(c=>[c.imageId,...(c.copies||[]).map(x=>x.imageId)]).filter(Boolean)}
function cardsVisible(){let arr=db.cards.filter(c=>(view.search||c.binderId===view.binder)&&matches(c)&&(!view.favorites||c.favorite));const [field,dir]=activeSort().split(':');if(field&&field!=='default')arr.sort((a,b)=>{let v;if(field==='date')v=(a.dateBought||'').localeCompare(b.dateBought||'');else v=String(a[field]||'').localeCompare(String(b[field]||''),undefined,{numeric:true,sensitivity:'base'});return dir==='desc'?-v:v});return arr}
function availableMeta(...values){return values.map(v=>String(v??'').trim()).filter(v=>v&&v!=='—'&&v!=='-').map(esc).join(' · ')}
function metaRow(...values){const line=availableMeta(...values);return line?`<div class="catalogueLine">${line}</div>`:''}
function detailMeta(...values){const line=availableMeta(...values);return line?`<p class="detailMeta">${line}</p>`:''}
function copyMeta(x){return availableMeta(x.condition,x.language,x.pack,displayDate(x.dateBought))}
function tagsHtml(c){return c.tags.map(t=>{const tag=db.tags.find(x=>x.id===t);return tag?`<small>${esc(tag.emoji||'🏷')}</small>`:''}).join('')}
function render(){const home=!view.binder&&!view.search&&!view.card;const inBinder=!!view.binder&&!view.card;const global=view.search&&!view.card;$('back').classList.toggle('hidden',home);$('search').value=draft;$('context').innerHTML='';$('chips').innerHTML=[...words.map((w,i)=>`<button class="chip" data-word="${i}" title="Remove keyword">${esc(w)} ×</button>`),...filters.map(t=>{const tag=db.tags.find(x=>x.id===t);return tag?`<button class="chip" data-tag="${esc(t)}" title="Remove tag">${esc(tag.emoji||'🏷')} ×</button>`:''}),...(view.favorites?[`<button class="chip" id="favoriteChip" title="Remove favorites filter">♥ FAVORITES ×</button>`]:[])].join('');$('chips').querySelectorAll('[data-word]').forEach(el=>el.onclick=()=>{words.splice(Number(el.dataset.word),1);view.search=!view.binder&&(!!words.length||!!filters.length||!!view.favorites);render()});$('chips').querySelectorAll('[data-tag]').forEach(el=>el.onclick=()=>{filters=filters.filter(t=>t!==el.dataset.tag);view.search=!view.binder&&(!!words.length||!!filters.length||!!view.favorites);render()});
if($('favoriteChip'))$('favoriteChip').onclick=()=>{view.favorites=false;if(!view.binder&&!words.length&&!filters.length&&!draft.trim())view.search=false;render()};$('add').title=home?'Add binder':'Add card';$('sort').classList.toggle('hidden',!!view.card);const bulk=$('bulk');bulk.classList.toggle('hidden',!editMode||home||!!view.card);if(!bulk.classList.contains('hidden'))renderBulk();
if(view.card){renderDetails();return}if(home){$('context').innerHTML=`<span class="homeCounts">${db.binders.length} BINDERS · ${db.cards.length} CARDS · ${db.cards.filter(c=>c.favorite).length} FAVORITES</span><button class="icon" id="manageBinders" title="Edit binders" aria-label="Edit binders">✎</button>`;$('manageBinders').onclick=()=>confirmEdit(()=>binderManager(),'your binders');$('content').innerHTML=db.binders.length?`<div class="grid">${[...db.binders].sort((a,b)=>sort==='name:asc'?a.name.localeCompare(b.name):sort==='name:desc'?b.name.localeCompare(a.name):0).map(b=>`<button class="binder" data-b="${esc(b.id)}"><div class="emoji">${esc(b.emoji||'📁')}</div><strong>${esc(b.name)}</strong><small>${db.cards.filter(c=>c.binderId===b.id).length} CARDS</small></button>`).join('')}</div>`:'<div class="empty">No binders yet.</div>';$('content').querySelectorAll('[data-b]').forEach(b=>b.onclick=()=>{view.binder=b.dataset.b;words=[];filters=[];draft='';editMode=false;selected.clear();render()});return}
const list=cardsVisible();$('context').innerHTML=global?`<span class="binderStats"><span class="binderCounter">${view.favorites?'FAVORITES · ALL BINDERS':'SEARCH ALL BINDERS'} · ${list.length} CARDS</span></span><button class="icon" id="toggleEdit"`:`<span class="binderStats"><span class="binderNameBadge">${esc(binderName(view.binder))}</span><span class="binderCounter">${db.cards.filter(c=>c.binderId===view.binder).length} CARDS · ${db.cards.filter(c=>c.binderId===view.binder&&c.favorite).length} FAVORITES</span></span><button class="icon" id="toggleEdit" title="${editMode?'Done':'Edit mode'}">${editMode?'✓':'✎'}</button>`;$('toggleEdit').onclick=()=>{if(!editMode)confirmEdit(()=>{editMode=true;render()},view.binder?'this binder':'these cards');else{editMode=false;selected.clear();render()}};
$('content').classList.toggle('compactView',prefs.catalogueView==='compact');$('content').innerHTML=list.length?list.map(c=>`<article class="entry" data-card="${esc(c.id)}">${editMode?`<input type="checkbox" data-check="${esc(c.id)}" ${selected.has(c.id)?'checked':''} aria-label="Select card">`:''}${c.imageId?`<img class="thumb" data-img="${esc(c.imageId)}" alt="">`:'<div class="thumb placeholder">▣</div>'}<div class="details"><strong class="cardName">${esc(c.name||'Untitled')}${(c.copies||[]).length?` <span class="copyBadge">×${(c.copies||[]).length+1}</span>`:''}</strong>${prefs.catalogueView==='compact'?metaRow(c.language,c.pack):`${metaRow(c.condition,c.language)}${metaRow(c.pack,displayDate(c.dateBought))}`}${global?`<small>📁 ${esc(binderName(c.binderId))}</small>`:''}${prefs.catalogueView==='compact'||!String(c.description||'').trim()?'':`<div class="catalogueDescription">${esc(c.description)}</div>`}${tagsHtml(c)}</div><button class="favoriteButton icon" data-fav="${esc(c.id)}" title="${c.favorite?'Remove favorite':'Add favorite'}" aria-label="Toggle favorite" aria-pressed="${!!c.favorite}">${c.favorite?'♥':'♡'}</button></article>`).join(''):'<div class="empty">No cards found.</div>';
$('content').querySelectorAll('[data-fav]').forEach(el=>el.onclick=e=>{e.stopPropagation();const id=el.dataset.fav;update(d=>{const c=d.cards.find(x=>x.id===id);if(c)c.favorite=!c.favorite})});$('content').querySelectorAll('[data-card]').forEach(el=>el.onclick=e=>{const id=el.dataset.card;if(editMode){if(e.target.matches('input')){e.stopPropagation();toggleSelect(id,e.target.checked)}else toggleSelect(id,!selected.has(id));return}view.card=id;render()});loadImages($('content'))}
function toggleSelect(id,yes){if(yes)selected.add(id);else selected.delete(id);render()}
function renderBulk(){
const list=cardsVisible(),all=list.length>0&&list.every(c=>selected.has(c.id));
const chosen=db.cards.filter(c=>selected.has(c.id));
const removeFavorite=chosen.length>0&&chosen.every(c=>c.favorite);
$('bulk').innerHTML=`<button id="selectAll" class="bulkSelect" title="${all?'Deselect visible':'Select all visible'}" aria-label="${all?'Deselect visible':'Select all visible'}">${all?'☑':'☐'}</button><span class="bulkCount">${selected.size} selected</span><div class="bulkActions"><button id="bulkMove" class="bulkIcon" title="Move selected" aria-label="Move selected">⇄</button><button id="bulkTag" class="bulkIcon" title="Tag selected" aria-label="Tag selected">🏷</button><button id="bulkFavorite" class="bulkIcon" title="${removeFavorite?'Unfavorite selected':'Favorite selected'}" aria-label="${removeFavorite?'Unfavorite selected':'Favorite selected'}">${removeFavorite?'♥':'♡'}</button><button id="bulkDelete" class="bulkIcon danger" title="Delete selected" aria-label="Delete selected">🗑</button></div>`;
$('selectAll').onclick=()=>{for(const c of list)all?selected.delete(c.id):selected.add(c.id);render()};
$('bulkMove').onclick=()=>{if(!selected.size)return notify('Select cards first');moveCards([...selected])};
$('bulkTag').onclick=()=>{if(!selected.size)return notify('Select cards first');bulkTags()};
$('bulkFavorite').onclick=()=>{if(!selected.size)return notify('Select cards first');update(d=>d.cards.filter(c=>selected.has(c.id)).forEach(c=>c.favorite=!removeFavorite))};
$('bulkDelete').onclick=()=>{if(!selected.size)return notify('Select cards first');deleteCards([...selected])};
}
function renderDetails(){const c=db.cards.find(x=>x.id===view.card);if(!c){view.card=null;render();return}$('context').innerHTML=`<span>${esc(binderName(c.binderId))}</span><button id="editCard" class="icon" title="Edit card">✎</button>`;$('editCard').onclick=()=>confirmEdit(()=>cardEditor(c.id));$('content').innerHTML=`<div class="panel" style="padding:18px"><div id="heroArea">${c.imageId?`<img class="hero" data-img="${esc(c.imageId)}" title="View image" alt="Card image">`:'<div class="empty">No image</div>'}</div><div class="detailHeading"><h2 class="detailTitle">${esc(c.name)} ${(c.copies||[]).length?`<span class="copyBadge">×${c.copies.length+1}</span>`:''}</h2><button id="detailFavorite" class="favoriteButton icon" title="Toggle favorite" aria-label="Toggle favorite" aria-pressed="${!!c.favorite}">${c.favorite?'♥':'♡'}</button></div>${detailMeta(c.condition,c.language)}${detailMeta(c.pack,displayDate(c.dateBought))}${c.description?`<p class="descriptionText">${esc(c.description)}</p>`:''}${(c.copies||[]).length?`<h3>COPIES</h3>${c.copies.map((x,i)=>`<div class="copyRow">${x.imageId?`<img class="copyThumb" data-img="${esc(x.imageId)}" data-copy-view="${i}" title="View copy image" alt="Copy ${i+2}">`:""}<span>Copy ${i+2}${copyMeta(x)?` · ${copyMeta(x)}`:''}${x.description?`<small class="copyDescription">${esc(x.description)}</small>`:""}</span><button class="icon" data-copy="${i}" title="Edit copy">✎</button></div>`).join('')}`:''}<div class="tags">${tagsHtml(c)}</div></div>`;loadImages($('content'));$('detailFavorite').onclick=()=>update(d=>{const x=d.cards.find(x=>x.id===c.id);if(x)x.favorite=!x.favorite});$('content').querySelectorAll('[data-copy]').forEach(b=>b.onclick=()=>confirmEdit(()=>copyEditor(c.id,Number(b.dataset.copy))));$('content').querySelectorAll('[data-copy-view]').forEach(b=>b.onclick=()=>imageViewer({...c,imageId:c.copies[Number(b.dataset.copyView)].imageId}));$('heroArea').onclick=()=>{if(c.imageId)imageViewer(c)}}
function goBack(){if(view.card){view.binder=db.cards.find(c=>c.id===view.card)?.binderId||view.binder;view.card=null}else{view.binder=null;view.search=false;view.favorites=false;words=[];filters=[];draft='';editMode=false;selected.clear()}render()}
$('back').onclick=goBack;$('add').onclick=()=>{if(!view.binder&&!view.search)binderEditor();else if(view.search&&!view.binder){if(!db.binders.length)return notify('Create a binder first');cardEditor()}else cardEditor()};
$('search').oninput=e=>{draft=e.target.value;const q=draft.trim().toLowerCase();$('searchSuggestions').classList.toggle('hidden',!q);$('searchSuggestions').innerHTML=q?((('favorites'.includes(q))&&!view.favorites)?`<button id="favoriteSuggestion" title="Show favorites">♥ FAVORITES</button>`:'')+db.tags.filter(t=>t.name.toLowerCase().includes(q)&&!filters.includes(t.id)).slice(0,8).map(t=>`<button data-sug="${esc(t.id)}">${esc(t.emoji||'🏷')} ${esc(t.name)}</button>`).join(''):'';if($('favoriteSuggestion'))$('favoriteSuggestion').onclick=()=>{view.favorites=true;draft='';if(!view.binder)view.search=!view.binder;$('searchSuggestions').classList.add('hidden');render()};$('searchSuggestions').querySelectorAll('[data-sug]').forEach(b=>b.onclick=()=>{filters.push(b.dataset.sug);draft='';view.search=!view.binder;$('searchSuggestions').classList.add('hidden');render()});if(view.binder||view.search)renderResultsOnly()};
function renderResultsOnly(){const cursor=document.activeElement=== $('search');if(cursor){const p=$('search').selectionStart;view.search=view.search||(!view.binder&&(!!words.length||!!filters.length||!!view.favorites));render();$('search').focus();$('search').setSelectionRange(p,p)}}
$('search').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();const w=draft.trim();if(w.toLowerCase()==='favorites'){view.favorites=true}else if(w&&!words.some(x=>x.toLowerCase()===w.toLowerCase()))words.push(w);draft='';view.search=!view.binder&&(!!words.length||!!filters.length||!!view.favorites);editMode=false;selected.clear();$('searchSuggestions').classList.add('hidden');render()}};
const sortOpts=[['default','Default order'],['name:asc','Name A–Z'],['name:desc','Name Z–A'],['condition:asc','Condition A–Z'],['condition:desc','Condition Z–A'],['language:asc','Language A–Z'],['language:desc','Language Z–A'],['pack:asc','Pack A–Z'],['pack:desc','Pack Z–A'],['date:desc','Date bought: Newest'],['date:asc','Date bought: Oldest']];$('sort').onclick=()=>{$('sortMenu').classList.toggle('hidden');$('sortMenu').innerHTML=sortOpts.map(([v,t])=>`<button data-sort="${v}">${activeSort()===v?'✓ ':''}${t}</button>`).join('');$('sortMenu').querySelectorAll('[data-sort]').forEach(b=>b.onclick=()=>{if(view.binder&&!view.search){prefs.binderSort={...(prefs.binderSort||{}),[view.binder]:b.dataset.sort};localStorage.setItem(PREF,JSON.stringify(prefs))}else sort=b.dataset.sort;$('sortMenu').classList.add('hidden');render()})};document.addEventListener('click',e=>{if(!e.target.closest('#sort,#sortMenu'))$('sortMenu').classList.add('hidden');if(!e.target.closest('#search,#searchSuggestions'))$('searchSuggestions').classList.add('hidden')});
function binderEditor(id){const b=db.binders.find(x=>x.id===id);modal(b?'Edit binder':'New binder',`<label class="field">Name<input id="bName" maxlength="80" value="${esc(b?.name||'')}"></label><label class="field">Emoji<input id="bEmoji" maxlength="12" value="${esc(b?.emoji||'📁')}"></label>`,[{text:'✕',title:'Cancel',fn:closeModal},{text:'✓',title:'Save',fn:()=>{const name=$('bName').value.trim();if(!name)return notify('Binder name required');const emoji=$('bEmoji').value.trim()||'📁';update(d=>{if(b){const item=d.binders.find(x=>x.id===id);item.name=name;item.emoji=emoji}else d.binders.push({id:uid(),name,emoji})});closeModal()}}])}
function binderManager(){modal('Manage binders',`<div id="binderList">${db.binders.map((b,i)=>`<div class="listRow"><span>${esc(b.emoji)} ${esc(b.name)} (${db.cards.filter(c=>c.binderId===b.id).length})</span><button data-up="${b.id}" title="Move up" ${i===0?'disabled':''}>↑</button><button data-down="${b.id}" title="Move down" ${i===db.binders.length-1?'disabled':''}>↓</button><button data-edit="${b.id}" title="Edit">✎</button><button data-del="${b.id}" title="Delete">🗑</button></div>`).join('')}</div>`,[{text:'＋',title:'New binder',fn:()=>binderEditor()},{text:'✓',title:'Done',fn:closeModal}]);$('binderList').querySelectorAll('[data-edit]').forEach(x=>x.onclick=()=>confirmEdit(()=>binderEditor(x.dataset.edit)));$('binderList').querySelectorAll('[data-del]').forEach(x=>x.onclick=()=>{const id=x.dataset.del,count=db.cards.filter(c=>c.binderId===id).length;confirmText('Delete binder?',`Delete ${esc(binderName(id))} and its ${count} cards? This cannot be undone.`,`DELETE`,()=>{const ids=db.cards.filter(c=>c.binderId===id).map(c=>c.imageId).filter(Boolean);update(d=>{d.binders=d.binders.filter(b=>b.id!==id);d.cards=d.cards.filter(c=>c.binderId!==id)});ids.forEach(deleteImage);view.binder=null;render()})});for(const dir of ['up','down'])$('binderList').querySelectorAll(`[data-${dir}]`).forEach(x=>x.onclick=()=>{update(d=>{const i=d.binders.findIndex(b=>b.id===x.dataset[dir]);const j=i+(dir==='up'?-1:1);[d.binders[i],d.binders[j]]=[d.binders[j],d.binders[i]]});binderManager()})}
function tagCheckboxes(ids=[]){
  const chosen=new Set(ids);
  const choices=db.tags.map(t=>`<button type="button" class="tagPickerOption" data-tag-id="${esc(t.id)}" aria-pressed="${chosen.has(t.id)}" title="${esc(t.name)}"><span class="tagPickerOptionName">${esc(t.emoji||'🏷')} ${esc(t.name)}</span><span class="tagPickerCheck">${chosen.has(t.id)?'✓':''}</span></button>`).join('');
  return `<details id="tagChoices" class="tagPickerDropdown"><summary class="tagPickerSummary"><span class="tagPickerSelected">${tagSummary(ids)}</span><span class="tagPickerChevron">▾</span></summary><div class="tagPickerOptions">${choices||'<p class="help">No tags yet. Create one in Settings → Tags.</p>'}</div></details>`;
}
function tagSummary(ids){const chosen=db.tags.filter(t=>ids.includes(t.id));return chosen.length?`<span class="tagPickerIcons">${chosen.map(t=>esc(t.emoji||'🏷')).join(' ')}</span><span class="tagPickerCount">${chosen.length} selected</span>`:'<span class="tagPickerHint">Select tags</span>'}
function selectedTags(){return [...$('tagChoices').querySelectorAll('.tagPickerOption[aria-pressed="true"]')].map(x=>x.dataset.tagId)}
// Delegated click handling keeps the dropdown open for multiple selections, including in bulk tagging.
document.addEventListener('click',e=>{const choice=e.target.closest('#tagChoices .tagPickerOption');if(!choice)return;const active=choice.getAttribute('aria-pressed')==='true';choice.setAttribute('aria-pressed',String(!active));choice.querySelector('.tagPickerCheck').textContent=active?'':'✓';const summary=$('tagChoices').querySelector('.tagPickerSelected');summary.innerHTML=tagSummary(selectedTags());markEditorDirty()});
function dateFields(prefix,iso){const parts=(dateInput(iso||new Date().toISOString().slice(0,10))||'').split('-');return `<div class="dateFields" role="group" aria-label="Date bought"><input id="${prefix}DD" inputmode="numeric" autocomplete="off" maxlength="2" placeholder="DD" aria-label="Day" value="${esc(parts[0]||'')}"><input id="${prefix}MM" inputmode="numeric" autocomplete="off" maxlength="2" placeholder="MM" aria-label="Month" value="${esc(parts[1]||'')}"><input id="${prefix}YYYY" inputmode="numeric" autocomplete="off" maxlength="4" placeholder="YYYY" aria-label="Year" value="${esc(parts[2]||'')}"></div>`}
function readDateFields(prefix){return parseDate([$(prefix+'DD').value.padStart(2,'0'),$(prefix+'MM').value.padStart(2,'0'),$(prefix+'YYYY').value].join('-'))}
function wireDateFields(prefix){const inputs=['DD','MM','YYYY'].map(x=>$(prefix+x));inputs.forEach((el,i)=>{el.addEventListener('input',()=>{el.value=el.value.replace(/\D/g,'').slice(0,i===2?4:2);if(i<2&&el.value.length===2)inputs[i+1].focus()})})}
function watchEditorChanges(){const root=$('modalRoot').querySelector('.modal');if(!root)return;root.dataset.editor='true';root.dataset.dirty='false';root.addEventListener('input',()=>root.dataset.dirty='true');root.addEventListener('change',()=>root.dataset.dirty='true');}
function markEditorDirty(){const root=$('modalRoot').querySelector('.modal[data-editor]');if(root)root.dataset.dirty='true'}
function safeCloseEditor(){const root=$('modalRoot').querySelector('.modal[data-editor]');if(root?.dataset.dirty==='true'){if(!window.confirm('Discard unsaved changes?'))return false}pendingImage=null;pendingCopyImage=null;closeModal();return true}
