function deleteCards(ids){if(!ids.length)return notify('Select cards first');confirmText('Delete cards?',`Permanently delete ${ids.length} selected card(s)?`,'DELETE',()=>{const images=db.cards.filter(c=>ids.includes(c.id)).flatMap(c=>[c.imageId,...(c.copies||[]).map(x=>x.imageId)]).filter(Boolean);update(d=>{d.cards=d.cards.filter(c=>!ids.includes(c.id))});images.forEach(deleteImage);selected.clear();if(ids.includes(view.card))view.card=null;render()})}
