function tagManager(){const counts=Object.fromEntries(db.tags.map(t=>[t.id,db.cards.filter(c=>c.tags.includes(t.id)).length]));modal('Manage tags',`<div class="row"><select id="tagSort"><option value="az">A–Z</option><option value="most">Most used</option><option value="least">Least used</option></select><button id="addTag" title="Add tag">＋</button><button id="cleanTags" title="Delete unused tags">🧹</button><button id="mergeTags" title="Merge tags">⇄</button></div><div id="tagList"></div>`,[{text:'✓',title:'Done',fn:closeModal}]);function draw(){const mode=$('tagSort').value;const list=[...db.tags].sort((a,b)=>mode==='az'?a.name.localeCompare(b.name):mode==='most'?counts[b.id]-counts[a.id]||a.name.localeCompare(b.name):counts[a.id]-counts[b.id]||a.name.localeCompare(b.name));$('tagList').innerHTML=list.map(t=>`<div class="listRow"><span>${esc(t.emoji||'🏷')} ${esc(t.name)} (${counts[t.id]})</span><button data-edit-tag="${esc(t.id)}" title="Edit tag">✎</button><button class="danger" data-del-tag="${esc(t.id)}" title="Delete tag">🗑</button></div>`).join('');$('tagList').querySelectorAll('[data-edit-tag]').forEach(b=>b.onclick=()=>confirmEdit(()=>tagEditor(b.dataset.editTag)));$('tagList').querySelectorAll('[data-del-tag]').forEach(b=>b.onclick=()=>{const id=b.dataset.delTag;confirmText('Delete tag?',`Delete this tag from the library and all assigned cards?`,'DELETE',()=>{update(d=>{d.tags=d.tags.filter(t=>t.id!==id);d.cards.forEach(c=>c.tags=c.tags.filter(t=>t!==id))});tagManager()})})}$('tagSort').onchange=draw;draw();$('addTag').onclick=()=>tagEditor();$('cleanTags').onclick=()=>{const ids=db.tags.filter(t=>!counts[t.id]).map(t=>t.id);if(!ids.length)return notify('No unused tags');confirmText('Delete unused tags?',`Delete ${ids.length} unused tag(s)?`,'DELETE',()=>{update(d=>d.tags=d.tags.filter(t=>!ids.includes(t.id)));tagManager()})};$('mergeTags').onclick=mergeTags}
function tagEditor(id){const t=db.tags.find(x=>x.id===id);modal(t?'Edit tag':'New tag',`<label class="field">Name<input id="tagName" value="${esc(t?.name||'')}"></label><label class="field">Emoji<input id="tagEmoji" value="${esc(t?.emoji||'🏷')}"></label>`,[{text:'✕',title:'Cancel',fn:closeModal},{text:'✓',title:'Save',fn:()=>{const name=$('tagName').value.trim(),emoji=$('tagEmoji').value.trim()||'🏷';if(!name)return notify('Name required');if(db.tags.some(x=>x.id!==id&&x.name.toLowerCase()===name.toLowerCase()))return notify('Tag already exists');update(d=>{if(t)Object.assign(d.tags.find(x=>x.id===id),{name,emoji});else d.tags.push({id:uid(),name,emoji})});tagManager()}}])}
function mergeTags(){if(db.tags.length<2)return notify('Need two tags');const opts=db.tags.map(t=>`<option value="${esc(t.id)}">${esc(t.emoji)} ${esc(t.name)}</option>`).join('');modal('Merge tags',`<label class="field">Source<select id="mergeFrom">${opts}</select></label><label class="field">Destination<select id="mergeTo">${opts}</select></label>`,[{text:'✕',title:'Cancel',fn:closeModal},{text:'→',title:'Continue',fn:()=>{const from=$('mergeFrom').value,to=$('mergeTo').value;if(from===to)return notify('Choose different tags');const n=db.cards.filter(c=>c.tags.includes(from)).length;confirmText('Merge tags?',`Move ${n} assignments to the destination tag and remove the source tag?`,'MERGE',()=>{update(d=>{d.cards.forEach(c=>{if(c.tags.includes(from))c.tags=[...new Set([...c.tags.filter(x=>x!==from),to])]});d.tags=d.tags.filter(t=>t.id!==from)});tagManager()})}}])}
const imageDB=new Promise((resolve,reject)=>{const req=indexedDB.open('card-archive-images-v1',1);req.onupgradeneeded=()=>req.result.createObjectStore('images');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});
async function imageTx(mode,operation){const dbi=await imageDB;return new Promise((resolve,reject)=>{const tx=dbi.transaction('images',mode),req=operation(tx.objectStore('images'));let result;req.onsuccess=()=>{result=req.result};req.onerror=()=>reject(req.error);tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||new Error('Image transaction aborted'))})}
const putImage=(id,blob)=>imageTx('readwrite',s=>s.put(blob,id));const loadImage=id=>imageTx('readonly',s=>s.get(id));const deleteImage=id=>imageTx('readwrite',s=>s.delete(id));
async function loadImages(root){for(const img of root.querySelectorAll('img[data-img]')){const id=img.dataset.img;try{const blob=await loadImage(id);if(!img.isConnected)continue;if(!(blob instanceof Blob)||!blob.size){img.alt='Image unavailable';img.classList.add('imageMissing');continue}const url=URL.createObjectURL(blob);img.onload=()=>{URL.revokeObjectURL(url);img.onload=null};img.onerror=()=>{URL.revokeObjectURL(url);img.alt='Image could not be displayed';img.classList.add('imageMissing')};img.src=url}catch(e){console.error('Image retrieval failed',id,e);if(img.isConnected){img.alt='Image unavailable';img.classList.add('imageMissing')}}}}
function cropImage(file,onDone){const img=new Image(),source=URL.createObjectURL(file);img.onload=()=>{URL.revokeObjectURL(source);const shade=document.createElement('div');shade.className='modalShade cropShade';shade.innerHTML=`<div class="modal"><h2>Crop image</h2><div class="cropSurface"><canvas id="cropCanvas"></canvas><div class="cropSelection" id="cropSelection"><i data-corner="tl"></i><i data-corner="tr"></i><i data-corner="bl"></i><i data-corner="br"></i></div></div><div class="row"><button id="cropRotate" title="Rotate image">⟳</button><button id="cropReset" title="Reset crop">↺</button></div><p class="help">Drag a corner to resize. Drag inside the rectangle to move the crop.</p><div class="actions"><button id="cropCancel" title="Cancel">✕</button><button id="cropSave" title="Save crop">✓</button></div></div>`;document.body.append(shade);const canvas=shade.querySelector('canvas'),ctx=canvas.getContext('2d'),sel=shade.querySelector('#cropSelection');let rotation=0,box={x:.1,y:.1,w:.8,h:.8};const draw=()=>{const rotated=rotation%180!==0;const iw=rotated?img.height:img.width,ih=rotated?img.width:img.height;const maxW=Math.min(440,window.innerWidth-68),maxH=Math.min(440,window.innerHeight*.48),scale=Math.min(maxW/iw,maxH/ih,1);canvas.width=Math.max(1,Math.round(iw*scale));canvas.height=Math.max(1,Math.round(ih*scale));ctx.save();ctx.translate(canvas.width/2,canvas.height/2);ctx.rotate(rotation*Math.PI/180);ctx.drawImage(img,-img.width*scale/2,-img.height*scale/2,img.width*scale,img.height*scale);ctx.restore();position()};function position(){sel.style.left=(box.x*100)+'%';sel.style.top=(box.y*100)+'%';sel.style.width=(box.w*100)+'%';sel.style.height=(box.h*100)+'%'}draw();let drag=null;sel.addEventListener('pointerdown',e=>{e.preventDefault();const corner=e.target.dataset.corner||'move';drag={corner,startX:e.clientX,startY:e.clientY,initial:{...box}};sel.setPointerCapture(e.pointerId)});sel.addEventListener('pointermove',e=>{if(!drag)return;const rect=canvas.getBoundingClientRect(),dx=(e.clientX-drag.startX)/rect.width,dy=(e.clientY-drag.startY)/rect.height,b={...drag.initial},min=.07;switch(drag.corner){case'tl':b.x+=dx;b.y+=dy;b.w-=dx;b.h-=dy;break;case'tr':b.y+=dy;b.w+=dx;b.h-=dy;break;case'bl':b.x+=dx;b.w-=dx;b.h+=dy;break;case'br':b.w+=dx;b.h+=dy;break;default:b.x+=dx;b.y+=dy}b.w=Math.max(min,Math.min(b.w,1));b.h=Math.max(min,Math.min(b.h,1));b.x=Math.max(0,Math.min(b.x,1-b.w));b.y=Math.max(0,Math.min(b.y,1-b.h));box=b;position()});sel.addEventListener('pointerup',()=>drag=null);sel.addEventListener('pointercancel',()=>drag=null);shade.querySelector('#cropRotate').onclick=()=>{rotation=(rotation+90)%360;box={x:.1,y:.1,w:.8,h:.8};draw()};shade.querySelector('#cropReset').onclick=()=>{box={x:.1,y:.1,w:.8,h:.8};position()};shade.querySelector('#cropCancel').onclick=()=>shade.remove();shade.querySelector('#cropSave').onclick=()=>{const out=document.createElement('canvas'),cw=Math.round(canvas.width*box.w),ch=Math.round(canvas.height*box.h),factor=Math.min(1,1600/Math.max(cw,ch));out.width=Math.max(1,Math.round(cw*factor));out.height=Math.max(1,Math.round(ch*factor));out.getContext('2d').drawImage(canvas,box.x*canvas.width,box.y*canvas.height,cw,ch,0,0,out.width,out.height);out.toBlob(blob=>{if(blob&&blob.size){onDone(blob);shade.remove()}else notify('Image conversion failed')},'image/jpeg',.83)}};img.onerror=()=>{URL.revokeObjectURL(source);notify('Cannot open image')};img.src=source}
function imageViewer(c){const root=document.createElement('div');root.className='viewer';root.innerHTML=`<div class="top"><button class="icon" id="viewBack" title="Back">←</button><div class="row"><button class="icon" id="viewEdit" title="Edit card">✎</button><button class="icon" id="viewClose" title="Close">✕</button></div></div><div class="stage"><img alt="Card image"></div><div class="hint">Pinch, scroll, or double-tap to zoom</div>`;document.body.append(root);const pic=root.querySelector('img');let scale=1,x=0,y=0;const pointers=new Map();let lastDistance=0,lastX=0,lastY=0;function apply(){pic.style.transform=`translate(${x}px,${y}px) scale(${scale})`}loadImage(c.imageId).then(blob=>{if(blob&&root.isConnected){const url=URL.createObjectURL(blob);pic.src=url;pic.onload=()=>URL.revokeObjectURL(url)}});const close=()=>root.remove();root.querySelector('#viewBack').onclick=close;root.querySelector('#viewClose').onclick=close;root.querySelector('#viewEdit').onclick=()=>confirmEdit(()=>{close();cardEditor(c.id)});const stage=root.querySelector('.stage');stage.onwheel=e=>{e.preventDefault();scale=Math.max(1,Math.min(8,scale*(e.deltaY<0?1.15:.87)));if(scale===1)x=y=0;apply()};stage.ondblclick=()=>{scale=scale>1?1:2.5;x=y=0;apply()};stage.onpointerdown=e=>{pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});stage.setPointerCapture(e.pointerId);lastX=e.clientX;lastY=e.clientY;lastDistance=0};stage.onpointermove=e=>{if(!pointers.has(e.pointerId))return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===2){const [a,b]=[...pointers.values()],d=Math.hypot(a.x-b.x,a.y-b.y);if(lastDistance)scale=Math.max(1,Math.min(8,scale*d/lastDistance));lastDistance=d}else if(scale>1){x+=e.clientX-lastX;y+=e.clientY-lastY;lastX=e.clientX;lastY=e.clientY}apply()};stage.onpointerup=stage.onpointercancel=e=>{pointers.delete(e.pointerId);lastDistance=0};root.onkeydown=e=>{if(e.key==='Escape')close()}}
const blobToData=blob=>new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=()=>rej(r.error);r.readAsDataURL(blob)});
const dataToBlob=data=>{const [meta,body]=data.split(',');if(!meta?.startsWith('data:image/')||!body)throw Error('Invalid image');const bytes=atob(body),arr=new Uint8Array(bytes.length);for(let i=0;i<bytes.length;i++)arr[i]=bytes.charCodeAt(i);return new Blob([arr],{type:meta.slice(5).split(';')[0]})};
async function exportBackup(){try{notify('Preparing backup…');const images={};for(const id of new Set(allImageIds(db.cards))){const blob=await loadImage(id);if(!blob)throw Error('Missing stored image '+id);images[id]=await blobToData(blob)}const data={format:'card-archive',version:1,exportedAt:new Date().toISOString(),binders:db.binders,cards:db.cards,tags:db.tags,images};const url=URL.createObjectURL(new Blob([JSON.stringify(data)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`card-archive-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);notify('Backup exported')}catch(e){notify('Export failed: '+e.message)}}
function validateBackup(x){if(!x||x.format!=='card-archive'||x.version!==1||!Array.isArray(x.binders)||!Array.isArray(x.cards)||!Array.isArray(x.tags)||!x.images||typeof x.images!=='object')throw Error('Not a compatible Card Archive backup');const ids=new Set(x.binders.map(b=>b.id));if(x.cards.some(c=>c.copies!==undefined&&(!Array.isArray(c.copies)||c.copies.some(p=>!p||typeof p!=='object'||p.imageId&&!x.images[p.imageId]))))throw Error('Invalid duplicate copy or missing image');if(x.binders.some(b=>!b.id||typeof b.name!=='string')||x.tags.some(t=>!t.id||typeof t.name!=='string')||x.cards.some(c=>!c.id||!ids.has(c.binderId)||typeof c.name!=='string'||!Array.isArray(c.tags)))throw Error('Backup contains invalid records');if(new Set(x.binders.map(b=>b.id)).size!==x.binders.length||new Set(x.cards.map(c=>c.id)).size!==x.cards.length||new Set(x.tags.map(t=>t.id)).size!==x.tags.length)throw Error('Duplicate record IDs');const tids=new Set(x.tags.map(t=>t.id));if(x.cards.some(c=>c.tags.some(t=>!tids.has(t))||c.imageId&&!x.images[c.imageId]))throw Error('Missing tag or image reference');for(const image of Object.values(x.images)){if(typeof image!=='string'||!/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/]+={0,2}$/.test(image))throw Error('Invalid image payload')}}
async function importBackup(file){let data;try{data=JSON.parse(await file.text());validateBackup(data)}catch(e){return notify('Invalid backup: '+e.message)}const existing=db.cards.length,coming=data.cards.length;modal('Restore backup',`<p>Backup verified: ${data.binders.length} binders, ${data.tags.length} tags, ${Object.keys(data.images).length} images. Current archive: <b>${existing}</b> cards. Backup: <b>${coming}</b> cards, ${data.binders.length} binders, ${data.tags.length} tags.</p><label class="field"><input type="radio" name="restore" value="add" checked style="width:auto"> Add all — keep existing cards, including duplicates</label><label class="field"><input type="radio" name="restore" value="replace" style="width:auto"> Replace all — remove current cards and binders</label><p class="help">Images are included. Back up your existing collection first.</p>`,[{text:'✕',title:'Cancel',fn:closeModal},{text:'→',title:'Continue',fn:()=>{const mode=document.querySelector('input[name=restore]:checked').value;confirmText('Confirm restore',mode==='add'?`Add ${coming} cards to the existing ${existing}?`:`Replace all ${existing} existing cards with ${coming} from the backup?`,mode==='add'?'ADD':'REPLACE',()=>{performRestore(data,mode).catch(e=>notify('Restore failed: '+e.message))})}}])}
async function performRestore(data,mode){const oldImageIds=mode==='replace'?allImageIds(db.cards):[];const next=mode==='replace'?initial():structuredClone(db),binderMap=new Map(),tagMap=new Map(),imageWrites=[];for(const b of data.binders){let found=mode==='add'?next.binders.find(x=>x.name.toLowerCase()===b.name.toLowerCase()):null;const id=found?.id||uid();binderMap.set(b.id,id);if(!found)next.binders.push({...b,id})}for(const t of data.tags){let found=mode==='add'?next.tags.find(x=>x.name.toLowerCase()===t.name.toLowerCase()):null;const id=found?.id||uid();tagMap.set(t.id,id);if(!found)next.tags.push({...t,id})}for(const c of data.cards){const id=uid(),imageId=c.imageId?uid():null;const copies=(c.copies||[]).map(copy=>{const newImageId=copy.imageId?uid():null;if(newImageId)imageWrites.push([newImageId,dataToBlob(data.images[copy.imageId])]);return {...copy,id:uid(),imageId:newImageId}});next.cards.push({...c,id,binderId:binderMap.get(c.binderId),tags:[...new Set(c.tags.map(t=>tagMap.get(t)))],imageId,copies});if(imageId)imageWrites.push([imageId,dataToBlob(data.images[c.imageId])])}const written=[];try{for(const [id,blob] of imageWrites){await putImage(id,blob);written.push(id)}save(next);view={binder:null,card:null,search:false};words=[];filters=[];draft='';editMode=false;selected.clear();closeModal();render();notify(`Restored ${data.cards.length} cards`);if(mode==='replace'){const retained=new Set(allImageIds(next.cards));for(const oldId of oldImageIds)if(!retained.has(oldId))await deleteImage(oldId).catch(()=>{})}}catch(e){for(const id of written)await deleteImage(id).catch(()=>{});throw e}}
render();

// Warn before navigating away from a dirty card/copy editor with browser Back.
window.addEventListener('popstate',()=>{if($('modalRoot').querySelector('.modal[data-editor]'))safeCloseEditor()});

// v0.2.7 — Match DA connection status: browser online/offline events.
const offlineInfo = document.getElementById('offlineInfo');
function updateConnectionLabel(){
  if(offlineInfo) offlineInfo.textContent = navigator.onLine ? 'NETWORK: ONLINE · CATALOGUE: ON THIS DEVICE' : 'NETWORK: OFFLINE · CATALOGUE: ON THIS DEVICE';
}
window.addEventListener('online', updateConnectionLabel);
window.addEventListener('offline', updateConnectionLabel);
updateConnectionLabel();
